use std::fs

fn find(ks: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < ks.len() as int {
        if ks[i as usize] == k { return i }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    let mut cap = 1
    let mut first = true
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 { continue }
        if first {
            cap = p[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        if p[0] == "put" {
            let k = p[1].parse::<int>().unwrap_or(0)
            let v = p[2].parse::<int>().unwrap_or(0)
            let i = find(ks, k)
            if i >= 0 {
                ks.remove(i as usize)
                vs.remove(i as usize)
            }
            ks.insert(0, k)
            vs.insert(0, v)
            if ks.len() as int > cap {
                let e = ks[ks.len() - 1]
                ks.remove(ks.len() - 1)
                vs.remove(vs.len() - 1)
                println("evict ${e}")
            }
        } else if p[0] == "get" {
            let k = p[1].parse::<int>().unwrap_or(0)
            let i = find(ks, k)
            if i < 0 {
                println("-1")
            } else {
                let v = vs[i as usize]
                ks.remove(i as usize)
                vs.remove(i as usize)
                ks.insert(0, k)
                vs.insert(0, v)
                println("${v}")
            }
        } else if p[0] == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut parts: Vec<string> = []
                for k in ks { parts.push("${k}") }
                println(parts.join(" "))
            }
        }
    }
}

